from pathlib import Path
import csv, html, json
R=Path(__file__).resolve().parent
E=html.escape
safe='https://www.safe.gov.cn/tianjin/2026/0713/3088.html'
recon='https://www.safe.gov.cn/tianjin/2026/0917/3134.html'
quota='https://www.safe.gov.cn/tianjin/2024/0621/2529.html'
rule='https://www.safe.gov.cn/tianjin/2024/0430/2464.html'
atm='https://www.safe.gov.cn/en/2017/1230/1397.html'
irs='https://www.irs.gov/individuals/international-taxpayers/foreign-tax-credit'
fx='https://www.govinfo.gov/content/pkg/USCODE-2024-title26/html/USCODE-2024-title26-subtitleA-chap1-subchapN-partIII-subpartJ-sec988.htm'
wise='https://wise.com/help/articles/2955298/guide-to-cny-transfers'
fee='https://www.hsbc.com.cn/content/dam/hsbc/cn/docs/document-download/tariff-of-Accounts-services-for-personal-customers-v2.pdf'
fbar='https://www.irs.gov/businesses/small-businesses-self-employed/report-of-foreign-bank-and-financial-accounts-fbar'
link=lambda url,text='Official source':f'<a href="{E(url,quote=True)}">{E(text)}</a>'
nav=[('index.html','Overview'),('routes.html','Methods & steps'),('costs.html','Cost table'),('review.html','Flagged for review')]
def page(name,title,body):
 n=''.join(f'<a {"aria-current=page" if a==name else ""} href="{a}">{b}</a>' for a,b in nav)
 (R/name).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | China money</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap"><a class="brand" href="index.html">CHINA MONEY <span> / INDEPENDENT REVIEW</span></a><nav aria-label="Main navigation">{n}</nav></div></header><main class="wrap"><p class="eyebrow">RESEARCH UPDATE · 8 NOV 2026</p><h1>{E(title)}</h1>{body}</main><footer><div class="wrap">General research, not legal or tax advice. No transfer or filing has been made. Do not put personal records in this public repository.</div></footer></body></html>''')
page('index.html','Move money with a clearer picture',f'''<p class="lede">A practical, source-linked review of moving RMB from mainland China to a U.S. account. The lowest-cost lawful route depends on where the money came from and the bank’s actual quote.</p><div class="callout"><strong>Best first route to investigate</strong><p>If the balance is your documented lawful China employment income, ask the Chinese bank to convert and remit it using ID, income-source records and relevant tax evidence. SAFE describes that route; it does not establish this account’s eligibility. {link(safe,'SAFE: employment income')}</p></div><div class="grid"><article><span>01 / DECIDE</span><h2>Separate tax from fees</h2><p>Source-income tax, foreign exchange spread, transfer charges, U.S. currency gain and filing penalties are different issues. An outstanding tax cannot be calculated from a transfer amount alone.</p><a href="routes.html">Compare methods →</a></article><article><span>02 / COMPARE</span><h2>40 amounts, no invented prices</h2><p>The matrix covers $10,000 to $400,000. Unknown total costs are blank—not zero. Quotes and personal eligibility were not supplied.</p><a href="costs.html">Open cost matrix →</a></article><article><span>03 / REVIEW</span><h2>Important discrepancies</h2><p>An older portal contains overbroad claims about small conversions and tax. The structural checks in this repo do not prove every claim.</p><a href="review.html">Review findings →</a></article></div><h2>Executive summary</h2><ol><li>First establish account ownership, original source, tax years and the written reason for the bank’s refusal. Do not assume conversion itself created the tax.</li><li>For documented eligible current-account income, use a regulated bank or a provider that accepts the source and your identity. Compare same-time, all-in quotes and receiver fees; no cheapest provider is established. {link(safe,'SAFE')}</li><li>For qualifying foreign income taxes, the U.S. foreign tax credit may reduce U.S. tax; foreign earned income exclusion has separate requirements and the same excluded income cannot also generate a foreign tax credit. {link(irs,'IRS foreign tax credit')}</li><li>Foreign accounts may trigger FBAR if their aggregate value exceeded $10,000 at any time in a calendar year; Form 8938 is separate and depends on circumstances. {link(fbar,'IRS FBAR')}</li><li>Do not use borrowed quotas, fabricated documents or underground swaps. If records or prior returns are missing, obtain regulated professional help before executing.</li></ol><div class="notice"><strong>Scope and limits.</strong> This follow-up checks selected material claims, not every line in the repository. Earlier dashboards contain additional routes and primary-source evidence, but are not all independently reverified here. <a href="../docs/index.html">Earlier dashboard</a> · <a href="../portal/index.html">Earlier portal (see cautions)</a> · <a href="../site/index.html">Other dashboard</a></div>''')
rows=[
('Documented salary/current-account bank wire','Foreign individual with lawful current-account RMB income, subject to bank review.','Strong audit trail; can address larger documented amounts.','Proof, possible branch visit, spread and wire costs.', '1. Establish source and amount; collect ID, employment/income records and applicable tax evidence. 2. Ask the bank which documents and authorizations it accepts. 3. Obtain executable FX and all wire/receiver charges; compare. 4. Convert to USD and instruct remittance to your own U.S. account. 5. Retain receipts and reconcile final credit.',safe),
('Wise, bank-app funding','Provider says eligible users who work/worked in China can send from CNY with required tax record and their own account; check current conditions.','Alternative quote and electronic funding.','Provider eligibility, limits and fees; not a bypass of compliance.', '1. Review current provider eligibility, recipient and tax-record requirements. 2. Set up your own USD recipient and request a quote. 3. Submit verification and fund only from your own eligible Chinese bank account as instructed. 4. Track provider review and delivery; retain records.',wise),
('Wise, Alipay funding','Same Wise service; eligible user and accepted Alipay payment required.','Alternative payment interface.','Not an independent annual allowance; individual availability and cost unknown.', '1. Check Wise eligibility and quote. 2. Submit requested verification. 3. Follow the provider’s Alipay payment screen from your own eligible account. 4. Confirm delivery and retain documentation.',wise),
('Reconvert unused previously exchanged RMB','Only unused RMB from prior foreign-currency exchange; original slip normally valid 24 months, with specified small-amount exceptions.','May fit genuine leftover travel funds.','Not a general shortcut for unexplained earnings; commercial costs unknown.', '1. Confirm money is unused RMB from a previous exchange. 2. Provide valid ID and original exchange receipt when required. 3. Ask the bank whether small-amount exceptions and current rules apply. 4. Obtain quote and comply with cash or remittance rules.',recon),
('Property-sale proceeds','Potential route only if owner, sale and supporting documents satisfy applicable rules.','May be available for genuine ownership and sale.','Separate capital/real-estate rules, taxes, registration and bank review; not automatically available.', '1. Identify ownership and sale proceeds. 2. Obtain registered sale documents and applicable tax records. 3. Ask the bank and local SAFE what procedures and approvals apply. 4. Convert/remit only after authorization and quote.',rule),
('Inheritance or qualifying emigrant property','Specific legal-status and asset conditions; prior SAFE/bank procedures must be checked.','Potential route for qualifying property.','Not a general salary channel; documentary and approval burden.', '1. Identify the specific property, beneficiary and qualifying status. 2. Ask the local SAFE and bank for the current personal-property transfer procedure. 3. Assemble legal and tax documents, then seek required approval. 4. Obtain quote and remit if approved.',rule),
('ATM cash withdrawal abroad','Requires working domestic card and compliant overseas withdrawal.','Can access spending cash abroad.','Not a direct large bank transfer; annual/per-card controls, cash risk and unknown charges.', '1. Verify card use abroad and issuer limits. 2. Withdraw within applicable limits. 3. Check ATM and issuer charges. 4. Retain records; do not borrow cards to evade limits.',atm),
('Lawful physical currency transport','Must first obtain the foreign currency lawfully; separate China export and U.S. reporting rules apply.','A delivery method for actual cash.','Loss/seizure risk, reporting and restrictions; no verified total cost.', '1. Verify current export permissions before travel. 2. Withdraw and carry only lawfully permitted amounts. 3. Declare physical currency as required when entering the U.S. 4. Deposit subject to receiving-bank rules.', 'https://www.fincen.gov/about-fincen/fincen-year-review'),
]
body='<p class="lede">Eligibility is conditional, never assumed. These are route families, not a promise that all are available for this balance. <a href="../docs/routes.html">View the earlier 22-entry catalog</a>; its entries include delivery arrangements and rejected workarounds, not 22 independent solutions.</p>'
for name,eligible,pro,con,steps,src in rows:
 body+=f'<article class="route"><h2>{E(name)}</h2><p><strong>Who it may fit:</strong> {E(eligible)}</p><p><strong>Pros:</strong> {E(pro)} <strong>Cons:</strong> {E(con)}</p><p><strong>Steps:</strong> {E(steps)}</p><p>{link(src)}</p></article>'
body+=f'<div class="notice"><strong>Do not use:</strong> borrowed quotas, fabricated invoices, and underground transactions. A compliant agent acting under documented authorization is not the same as borrowing their quota. {link(rule,"SAFE implementing rules")}</div>'
page('routes.html','Methods & execution',body)
# Preserve all legacy route names for coverage, but make no assertion that each is an actual conversion route.
findings=json.loads((R.parent/'research/findings.json').read_text()); sources={s['id']:s['url'] for s in json.loads((R.parent/'research/sources.json').read_text())}
methods=[r for r in findings if r['category']=='routes']
assert len(methods)==22
with (R/'cost-matrix.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['route_id','route_name','target_usd','fx_spread_usd','transfer_fees_usd','tax_and_penalties_usd','total_cost_usd','status','source_context_url'])
 for m in methods:
  for i in range(1,41):w.writerow([m['id'],m['topic'],i*10000,'','','','','Unverified; applicability not assumed',sources[m['sources'][0]]])
summary=''.join(f'<tr><th scope="row">${i*10000:,.0f}</th><td></td><td></td><td></td><td><a href="{safe}">SAFE</a></td></tr>' for i in range(1,41))
details=''
for m in methods:
 s=sources[m['sources'][0]]
 rr=''.join(f'<tr><th scope="row">${i*10000:,.0f}</th><td></td><td></td><td></td><td></td><td>{link(s,"Source context")}</td></tr>' for i in range(1,41))
 details+=f'<details><summary>{E(m["id"])} · {E(m["topic"])}</summary><p>All cost cells unverified and blank. This source describes route or regulatory context, not an executable cost quote. This route may be conditional, prohibited, or not produce a USD deposit; see the <a href="../docs/routes.html#{E(m["id"])}">original entry</a>.</p><div class="scroll"><table><thead><tr><th>USD target</th><th>FX spread USD</th><th>Fees USD</th><th>Tax / penalty USD</th><th>Total USD</th><th>Source context</th></tr></thead><tbody>{rr}</tbody></table></div></details>'
page('costs.html','Cost comparison',f'''<p class="lede">Every amount from $10,000 to $400,000 in $10,000 increments. Target means USD delivered, not CNY sent. <strong>Blank means unverified, not zero or unavailable.</strong> It also does not mean the method is eligible at that amount.</p><div class="notice">A real total requires an eligible route, executable CNY/USD quote, exact debit and credit, all sender/correspondent/recipient fees, and personal tax/basis facts. A generic government link cannot establish a private account’s pricing. We cannot rank or calculate totals without those inputs.</div><h2>At a glance</h2><p>All methods: unverified. Full 22-entry breakdown below and <a href="cost-matrix.csv">downloadable CSV</a>.</p><div class="scroll"><table><thead><tr><th>USD target</th><th>Execution costs USD</th><th>Tax / penalties USD</th><th>Total USD</th><th>Source context</th></tr></thead><tbody>{summary}</tbody></table></div><h2>By route · 40 increments each</h2><p>Expand a route for its matrix. Rejected workarounds and spending-only arrangements are included solely for comparison, not as recommendations.</p>{details}<h2>Example of a published fee, not your total</h2><p>HSBC China’s effective 31 October 2026 tariff describes a Premier telegraphic-transfer issuance charge of 0.1%, with CNY100 minimum and CNY500 maximum, plus CNY120 per cable under the Premier column (item 2.2.4.2); eligibility and other institutions’ charges vary. This is not a live FX quote or an all-in quote for your bank. {link(fee,'HSBC China tariff, item 2.2.4.1')}</p><h2>What the conversion “penalty” can contain</h2><p>Compare the same-time reference rate to the executed rate; separately include sender, intermediary and recipient fees. Source-income tax or noncompliance penalties depend on the circumstances and are not assumed to be a conversion fee. A U.S. foreign-currency gain may require separate analysis. {link(fx,'26 U.S.C. § 988, 2024 edition')}</p>''')
flags=[('Small conversion is not a universal allowance','portal/methods.html M03 and portal/index.html','Older portal describes a passport-only $500/day walk-in for any RMB balance and advertises it prominently. SAFE’s wording covers reconversion of unused RMB from a previous exchange, not undocumented salary. Treat that portal claim as misleading.',recon),('Foreign purchase quota not uniform','portal/tax-compliance.html TC-12','Older portal categorically says foreign passport holders have a settlement quota only. SAFE says a foreign permanent resident ID holder has a purchase facilitation quota; eligibility and bank treatment are case-specific.',quota),('Tax must be established, not assumed','portal/methods.html M01 and M02','The portal assigns a 0% extra conversion tax, presumes tax paid and implies no tax proof in every reconversion; the cited sources do not establish the individual tax outcome. Treat the asserted percentage as unverified.',safe),('Blanket treaty/credit recommendation','portal/conversion-penalties.html CP-04 and CP-05','Always filing a treaty claim or a 10% cap cannot be assumed for each taxpayer or income item; residence, beneficial ownership, treaty exceptions and applicable tax need examination. IRS says treaty-entitled reduced tax only may qualify as credit.',irs),('Currency disposition is not automatically capital gain','portal/index.html and conversion-penalties.html CP-11','Portal suggests reporting a USD capital gain on Schedule D; statutory §988 generally treats covered FX gain as ordinary, while the personal-transaction exception has conditions. The 2024 code is a dated edition; determine current law and facts.',fx),('Provider and transfer cost data missing','All cost estimates','No case-specific live rates, fees, source of funds or tax basis were provided. An official link in a row supplies context, not verification of a numerical fee. All total-cost cells remain blank.',fee),('Review coverage not complete','Repository-wide','Prior reports claim line-by-line verification. This follow-up did not independently check every claim, every linked source or historical rule; automated domain/link checks do not establish substantive truth.',safe),('Open parallel work','PR #12','An open parallel PR contains overbroad claims in its description. A review comment was left; it was not merged by this session. Its status may change independently.',quota)]
t=''.join(f'<tr><th scope="row">{E(a)}</th><td>{E(b)}</td><td>{E(c)}</td><td>{link(u)}</td></tr>' for a,b,c,u in flags)
page('review.html','Flagged for review',f'''<p class="lede">These findings do not certify the rest of the repository. They identify concrete, potentially consequential issues for manual follow-up.</p><div class="scroll"><table><thead><tr><th>Issue</th><th>Location</th><th>Finding</th><th>Source</th></tr></thead><tbody>{t}</tbody></table></div><p>Corrections were requested in the shared task board rather than modifying files owned by other sessions. Other uncertainties remain on the <a href="../docs/review.html">original review page</a>.</p>''')
